"""Canonical typed records and publication-aware revision reconciliation."""
from typing import NamedTuple
from common import need, ident, decimal, address, decode64, reference


class Put(NamedTuple):
    op: str
    lease: str
    event: int
    probe: str
    target: int
    responder: object
    result: str
    service: str
    attempt: object
    payload: bytes


class Record(NamedTuple):
    kind: str
    id: str
    revision: int
    published: int
    content: object  # Put, or None for a tombstone


def parse_record(values, context, lookup):
    need(len(values) == 14)
    kind, name, rev, pub, op, lease, event, probe, target, responder, result, service, attempt, payload = values
    need(kind in ('icmp', 'app') and ident(name) and op in ('put', 'delete'))
    revision = decimal(rev, 10**9)
    published = decimal(pub)
    if op == 'delete':
        need(all(v == '' for v in values[5:]))
        return Record(kind, name, revision, published, None)
    need(reference(lease, context['leases']))
    event = decimal(event)
    interval = context['leases'][lease]
    need(interval['start'] <= event < interval['end'] and event <= published)
    target = address(target)
    if kind == 'icmp':
        need((lease, probe) in lookup and target == lookup[lease, probe][0])
        need(result in ('echo', 'error', 'timeout'))
        need(service == '' and attempt == '' and payload == '')
        if result == 'timeout':
            need(responder == '')
            responder = None
        else:
            responder = address(responder)
        attempt = None
        payload = b''
    else:
        need(probe == '' and responder == '' and reference(service, context['services']))
        need(result in ('open', 'closed', 'timeout'))
        attempt = decimal(attempt, 10**6)
        if result != 'open' or context['services'][service] == 'tcp':
            need(payload == '')
        payload = decode64(payload)
        need(len(payload) <= 65536)
        responder = None
    content = Put(op, lease, event, probe, target, responder, result, service, attempt, payload)
    return Record(kind, name, revision, published, content)


class Ledger:
    """Advance through query times, keeping only the highest visible revision.

    A set of canonical contents at that revision distinguishes replication from
    conflict. Publication and presentation spellings are deliberately absent
    from the content key; a tombstone is the single canonical value None.
    """
    def __init__(self, records):
        self.records = sorted(records, key=lambda row: row.published)
        self.position = 0
        self.state = {}
        self.time = -1

    def at(self, time):
        if time < self.time:
            self.position = 0
            self.state.clear()
        self.time = time
        while self.position < len(self.records):
            row = self.records[self.position]
            if row.published > time:
                break
            self.position += 1
            key = (row.kind, row.id)
            old = self.state.get(key)
            if old is None or row.revision > old[0]:
                self.state[key] = (row.revision, {row.content})
            elif row.revision == old[0]:
                old[1].add(row.content)
        counts = {'live': 0, 'deleted': 0, 'conflict': 0}
        live = []
        for (kind, name), (revision, contents) in self.state.items():
            if len(contents) != 1:
                counts['conflict'] += 1
            else:
                content = next(iter(contents))
                if content is None:
                    counts['deleted'] += 1
                else:
                    counts['live'] += 1
                    live.append((kind, content))
        return counts, live
